// Distinct ordered triples provide 3,700 new moves without duplicate recipes.
Object.entries(SOUL_SPECIALS).forEach(([cid,attacks],hero)=>{
 const theme=attacks[0].name;
 for(let i=0;i<50;i++){
  const recipe=hero*50+i,first=Math.floor(recipe/(18*17)),rest=recipe%(18*17);
  const remaining=Array.from({length:19},(_,n)=>n).filter(n=>n!==first);
  const second=remaining[Math.floor(rest/17)];
  const third=remaining.filter(n=>n!==second)[rest%17];
  const phases=[first,second,third];
  attacks.push({id:'s'+(i+3),slot:i+3,name:theme+' · '+phases.map(n=>SOUL_MECHANICS[n][0]).join(' → '),
   cost:6+i%5,duration:7400,signature:recipe%222,variant:hero%4,phases,
   desc:'Три последовательные фазы: '+phases.map((n,j)=>(j+1)+'. '+SOUL_MECHANICS[n][1]).join('; ')+'. · '+SOUL_VARIANTS[hero%4]});
 }
});
