 $('soul-score').innerHTML=d.teams.map((t,i)=>`<div><b>${escHTML(t.name||'Игрок '+(i+1))}</b><span>${d.hp[i]} / ${d.boss&&i===d.bossIndex?500:100} HP${i===me?' · ты':''}</span><meter min="0" max="${d.boss&&i===d.bossIndex?500:100}" value="${d.hp[i]}"></meter></div>`).join('');
