 if(!d.wave){const canvas=$('soul-canvas'),ctx=canvas.getContext('2d');ctx.fillStyle='#14121d';ctx.fillRect(0,0,600,400);ctx.fillStyle='#e96c82';ctx.font='30px serif';ctx.textAlign='center';ctx.fillText(d.over?'ДУЭЛЬ ОКОНЧЕНА':'♥',300,210);}
