  if(defender)ctx.fillText(`HP: ${Math.min(SOUL.boss&&(botDefender||soulPlayer()===SOUL.bossIndex)?500:100,Math.max(0,SOUL.hp[SOUL.boss?(botDefender?SOUL.bossIndex:soulPlayer()):1-SOUL.attacker]-v.damage))}`,14,46);
