function soulHarmful(p,moving){return !p.color||p.color==='cyan'&&moving||p.color==='orange'&&!moving;}

function soulSpecialHazards(w,t){
 const a=soulSpecial(w.cid,w.kind);
 if(a.phases){
  const out=[];
  a.phases.forEach((kind,phase)=>{
   const age=t-phase*1.9;
   if(age>=0&&age<3.1)out.push(...soulMechanicHazards(w,age,kind,a.variant,'phase'+phase));
  });
  return out;
 }
 const main=a.slot===1?a.secondary:a.mechanic;
 const out=soulMechanicHazards(w,a.slot===2?t*.93:t,main,a.variant,'main');
 if(a.slot===2&&t>=2.1)out.push(...soulMechanicHazards(w,t-2.1,a.secondary,(a.variant+1)%4,'final'));
 if(a.variant===3&&t>=1.1&&a.slot!==2)out.push(...soulMechanicHazards(w,t-1.1,main,0,'echo').filter((_,i)=>i%3===0));
 return out;
}

function soulBlasterHazards(w,t){
 const out=[],seed=w.seed%997/997;
 const beam=(id,x,y,angle,length,phase,width=13)=>{
  if(phase<0||phase>1.35)return;
  const warn=phase<.75;
  out.push({id,x,y,r:warn?3:width,h:length/2,angle,rect:true,warn,karma:!warn});
  // Skull at the beam origin; it is a visual warning, never a contact hazard.
  out.push({id:id+'head',x:x+Math.sin(angle)*length/2,y:y-Math.cos(angle)*length/2,r:20,warn:true,text:'☠'});
 };
 // First: two locked crossing shots. Then: diagonal pairs. Finale: rotating cross.
 for(let i=0;i<3;i++){
  const phase=t-.4-i*1.65,x=110+(seed*320+i*137)%380,y=100+(i*67)%200;
  const angle=i===0?0:i===1?Math.PI/4:Math.PI/2;
  beam('gaster-v'+i,x,200,angle,850,phase);
  beam('gaster-h'+i,300,y,angle+Math.PI/2,850,phase-.25);
 }
 if(t>4.8){const phase=t-4.8,angle=.25+Math.max(0,phase-.75)*.48;
  beam('gaster-final-a',300,200,angle,850,phase,11);
  beam('gaster-final-b',300,200,angle+Math.PI/2,850,phase,11);
 }
 return out;
}

// Transform a soul into the same local coordinates used to draw rotated beams.
function soulContact(p,x,y){
 if(!p.rect)return Math.hypot(x-p.x,y-p.y)<p.r+7;
 const a=p.angle||0,dx=x-p.x,dy=y-p.y;
 return Math.abs(dx*Math.cos(a)+dy*Math.sin(a))<p.r+6&&Math.abs(-dx*Math.sin(a)+dy*Math.cos(a))<(p.h||p.r)+6;
}

// Input sets a destination; only animation frames can move the defending soul.
function soulMove(v,dx,dy,speed,dt,mode,elapsed){
 if(dx||dy)v.pointerTarget=null;
 let tx=v.x+dx*speed*dt,ty=v.y+dy*speed*dt;
 if(v.pointerTarget){tx=v.pointerTarget.x;ty=v.pointerTarget.y;}
 if(mode==='web'){
  v.lane??=2;
  if(v.pointerTarget)v.lane=Math.max(0,Math.min(2,Math.round((ty-100)/100)));
  else if(dy&&elapsed-(v.laneAt??-180)>=180){v.lane=Math.max(0,Math.min(2,v.lane+Math.sign(dy)));v.laneAt=elapsed;}
  ty=100+v.lane*100;
 }
 const mx=tx-v.x,my=ty-v.y,distance=Math.hypot(mx,my);
 const step=Math.min(distance,speed*dt);
 if(distance>0){v.x+=mx/distance*step;v.y+=my/distance*step;}
 v.x=Math.max(10,Math.min(590,v.x));v.y=Math.max(10,Math.min(390,v.y));
}

// Phase-based mechanics; the same seeded attack can be drawn on both devices.
function soulMechanicHazards(w,t,kind,variant,tag){
 const signature=w.manualSignature??soulSpecial(w.cid,w.kind).signature;
 const out=[],seed=((w.seed+signature*37)%997)/997,shape=w.cid==='catalog'?'crystal':combatStyle(w.cid).type;
 const add=(id,x,y,r=8,extra={})=>out.push({id:tag+':'+id,x,y,r,shape,...extra});
 const rect=(id,x,y,r,h,extra={})=>add(id,x,y,r,{rect:true,h,...extra});
 const reflect=(x,max)=>{const z=((x%(2*max))+2*max)%(2*max);return z>max?2*max-z:z;};
 const ring=(id,x,y,radius,count,gap,offset,extra={})=>{for(let j=0;j<count;j++){if((j-gap+count)%count<4)continue;const a=j/count*Math.PI*2+offset;add(id+':'+j,x+Math.cos(a)*radius,y+Math.sin(a)*radius,7,extra);}};
 for(let row=0;row<6;row++){
  const age=t-.65-row*(.76+signature*.00065);if(age<0||age>3)continue;
  const x=80+(row*127+seed*270)%440,y=65+(row*83+seed*190)%270,angle=row*.9+seed*3;
  const warn=age<.55,fly=Math.max(0,age-.55),id=String(row);
  switch(kind){
   case 0:{
    w.marks??={};const key=tag+id;
    if(warn)w.marks[key]={x:w.x??x,y:w.y??y};
    const target=w.marks[key]||{x,y};
    if(age<1.1){rect(id+'v',target.x,200,warn?3:9,200,{warn});if(row%2)rect(id+'h',300,target.y,300,warn?3:8,{warn});}break;
   }
   case 1:for(let j=0;j<4;j++)add(id+j,reflect(x+age*(150+j*19),600),reflect(y+age*(95+j*23)*(row%2?-1:1),400),9);break;
   case 2:ring(id,300,200,Math.max(32,355-age*119),26,(row*3+variant)%26,angle*.12);break;
   case 3:
    if(age<.85)add(id+'mine',x,y,18,{warn:true,text:'!'});
    else for(let j=0;j<7;j++){const a=j*Math.PI*2/7+angle;add(id+j,x+Math.cos(a)*(age-.85)*176,y+Math.sin(a)*(age-.85)*176,7);}break;
   case 4:
    for(let j=0;j<5;j++){const a=j*Math.PI*2/5+angle+Math.min(age,1)*1.7,r=age<1?65:65+(age-1)*182;add(id+j,300+Math.cos(a)*r,200+Math.sin(a)*r,8,{warn:age<.3});}break;
   case 5:for(let j=0;j<4;j++){const d=age<1.5?age*285:(3-age)*285;add(id+j,row%2?600-d:d,55+j*92+Math.sin(age*3)*18,10,{shape:'slash'});}break;
   case 6:if(age<1.1)rect(id,300,y,300,warn?3:15,{warn,color:row%2?'orange':'cyan'});break;
   case 7:
    if(age<.7)add(id,x,age*210,16,{warn:age<.3});
    else for(let j=0;j<3;j++){const a=Math.PI/2+(j-1)*.62;add(id+j,x+Math.cos(a)*(age-.7)*220,147+Math.sin(a)*(age-.7)*220,8);}break;
   case 8:{const gap=300+Math.sin(age*1.6+row*.5+seed)*155;
    for(let j=0;j<19;j++){const px=j*34;if(Math.abs(px-gap)>66)add(id+j,px,-20+age*208,8);}break;}
   case 9:for(let j=0;j<4;j++){add(id+j,-25+age*246,60+j*90,8);if(age>.65)add(id+'e'+j,625-(age-.65)*246,70+j*90,8);}break;
   case 10:{const a=Math.sin(age*2.6+row)*1.05;
    rect(id,300,70,5,125,{angle:a,warn});add(id+'tip',300-Math.sin(a)*125,70+Math.cos(a)*125,17,{warn});break;}
   case 11:if(age<1.25)for(let j=0;j<2;j++)rect(id+j,180+j*240,200,warn?2:8,290,{angle:angle*.2+fly*.35,warn});break;
   case 12:
    add(id+'in',70,y,19,{warn:true,text:'○'});add(id+'out',530,400-y,19,{warn:true,text:'○'});
    for(let j=0;j<3;j++){const d=age*215-j*38;add(id+j,d<240?70+d:530-(d-240),d<240?y:400-y,8);}break;
   case 13:for(let j=0;j<7;j++){const a=angle+j*Math.PI*2/7+age*(row%2?-1:1);add(id+j,300+Math.cos(a)*age*147,200+Math.sin(a)*age*147,7);}break;
   case 14:{const gap=90+(row*59+seed*130)%230;
    const px=650-age*250;rect(id+'top',px,gap/2,12,gap/2-35,{warn:age<.35});rect(id+'bottom',px,(gap+400)/2,12,(400-gap)/2-35,{warn:age<.35});break;}
   case 15:ring(id,300,200,55+age*110,22,row*3%22,angle*.2,{color:row%2?'orange':'cyan'});break;
   case 16:if(age<1.05){rect(id+'slash',300,200,warn?2:9,340,{angle:angle,warn});}else if(age<1.8)rect(id+'mirror',300,200,age<1.3?2:9,340,{angle:-angle,warn:age<1.3});break;
   case 17:{
    w.marks??={};const key=tag+id;if(warn)w.marks[key]={x:w.x??300,y:w.y??200};const target=w.marks[key]||{x:300,y:200};
    const a=Math.atan2(target.y-y,target.x-x);
    for(let j=0;j<4;j++){const d=Math.max(0,fly*245-j*28);add(id+j,x+Math.cos(a)*d,y+Math.sin(a)*d,7,{warn});}break;
   }
   case 18:if(age<1.15){rect(id+'x',x,y,warn?28:80,warn?2:8,{warn});rect(id+'y',x,y,warn?2:8,warn?28:80,{warn});}
    else for(let j=0;j<4;j++){const a=j*Math.PI/2+angle;add(id+j,x+Math.cos(a)*(age-1.15)*215,y+Math.sin(a)*(age-1.15)*215,8);}break;
  }
 }
 if(variant===1)out.forEach((p,i)=>{if(!p.color&&i%3===0){p.color=Math.floor(t/1.4)%2?'orange':'cyan';if(t%1.4<.15)p.warn=true;}});
 if(variant===2)out.forEach(p=>{const x=p.x;p.x=300+(p.y-200)*1.35;p.y=200-(x-300)/1.35;if(p.rect){const r=p.r;p.r=p.h*1.35;p.h=r/1.35;p.angle=-(p.angle||0);}});
 return out;
}

function soulFilterCatalog(value){
 const query=value.trim().toLocaleLowerCase('ru');
 let count=0;document.querySelectorAll('.soul-catalog-grid button').forEach(button=>{button.hidden=!button.textContent.toLocaleLowerCase('ru').includes(query);if(!button.hidden)count++;});
 $('soul-catalog-count').textContent=count?'Найдено приёмов: '+count:'Ничего не найдено. Измени запрос.';
}
function soulUndertaleHazards(w,t){
 const n=Number(w.kind.slice(1))-45,out=[],seed=w.seed%997/997;
 const add=(id,x,y,r=8,extra={})=>out.push({id:'ut'+n+':'+id,x,y,r,...extra});
 const rect=(id,x,y,r,h,extra={})=>add(id,x,y,r,{rect:true,h,...extra});
 const ring=(id,x,y,r,count=14,extra={})=>{for(let j=0;j<count;j++){if(j<3)continue;const a=j*Math.PI*2/count+seed+Math.floor(t)*.2;add(id+':'+j,x+Math.cos(a)*r,y+Math.sin(a)*r,7,extra);}};
 for(let row=0;row<7;row++){
  const age=t-.7-row*.66;if(age<0||age>3.4)continue;
  const x=65+(row*113+seed*230)%470,id=String(row);
  switch(n){
   case 0:add(id,-30+age*230,360-Math.abs(Math.sin(age*2.1))*230,13,{text:'˄'});break;
   case 1:for(let j=0;j<4;j++)add(id+j,-20+age*215,200+(j-1.5)*40+Math.sin(age*3+row)*45,6);break;
   case 2:for(let j=0;j<8;j++){if(j===row%8||j===(row+1)%8)continue;const a=j*Math.PI/4+age*.8;add(id+j,300+Math.cos(a)*(70+age*45),200+Math.sin(a)*(70+age*45),8,{text:'×'});}break;
   case 3:for(let j=0;j<8;j++){if(j===row%8||j===(row+1)%8)continue;add(id+j,35+j*75+Math.sin(age*4+j)*18,-20+age*156,12);}break;
   case 4:ring(id,row%2?440:160,120,age*128);break;
   case 5:for(let j=0;j<6;j++)add(id+j,50+j*100,-20+age*185,10,{color:j===row%6?'green':undefined,text:'♣'});break;
   case 6:add(id,110+row*60,360-Math.abs(Math.sin(age*4))*38,14,{text:'×'});if(age>1)for(let j=0;j<3;j++)add(id+j,110+row*60+(j-1)*(age-1)*70,350-(age-1)*125,6);break;
   case 7:for(let j=0;j<3;j++)add(id+j,90+j*210+Math.sin(age*4+row)*32,-20+age*196,8);break;
   case 8:{const radius=age<1?20+age*45:65+(age-1)*155;for(let j=0;j<9;j++)add(id+j,300+Math.cos(j*Math.PI/4)*radius,100+Math.sin(j*Math.PI/4)*radius*.4+age*35,7,{warn:age<.35});break;}
   case 9:add(id,age<1.5?-20+age*385:557-(age-1.5)*385,70+row*45+(age>1.5?30:0),10,{shape:'crystal'});break;
   case 10:if(age<1.5)add(id,x,-20+age*210,12,{shape:'crystal'});else for(let j=0;j<2;j++)add(id+j,x+(j?1:-1)*(age-1.5)*210,295-(age-1.5)*65,7,{shape:'crystal'});break;
   case 11:for(let j=0;j<3;j++)add(id+j,row%2?620-age*190:-20+age*190,(row%2?35:240)+j*48+age*30,7);break;
   case 12:rect(id,-25+age*240,200,12,200,{color:'cyan'});break;
   case 13:for(let j=0;j<2;j++)rect(id+j,j?620-age*225:-20+age*225,200,10,140,{angle:j?-.4:.4,color:j?'orange':'cyan'});break;
   case 14:if(age<1.25)rect(id,x,400-(age<.55?10:(age-.55)*220)/2,12,(age<.55?10:(age-.55)*220)/2,{warn:age<.55,text:'ω'});break;
   case 15:add(id,x,-20+age*220,9,{shape:'crystal'});rect(id+'guard',620-age*190,365,25,18,{text:'ω'});break;
   case 16:for(let j=0;j<2;j++){const a=age*2+row;add(id+j,300+Math.sin(a)*(j?180:-180),200+Math.sin(a*2)*110,10);}break;
   case 17:{const a=Math.sin(age*2+row)*.7;add(id,x+Math.sin(a)*65,age<1.2?70+Math.cos(a)*65:135+(age-1.2)*210,11,{warn:age<.3});break;}
   case 18:rect(id,640-age*235,382,12,18+(row%3)*15);break;
   case 19:if(age<1.8){const h=age<.6?4:Math.sin((age-.6)/1.2*Math.PI)*125;rect(id,x,row%2?h/2:400-h/2,13,h/2,{warn:age<.6});}break;
   case 20:{const gap=190+Math.sin(row*.6+seed)*90,px=640-age*228;rect(id+'t',px,(gap-55)/2,12,(gap-55)/2);rect(id+'b',px,(gap+455)/2,12,(345-gap)/2);break;}
   case 21:{const px=age<1.4?650-age*320:age<1.75?202:202+(age-1.75)*320;rect(id,px,55+row%4*95,10,35,{color:row%3===0?'cyan':undefined});break;}
   case 22:for(let j=0;j<4;j++){const a=j*Math.PI/2+age*(row%2?-1:1);add(id+j,300+Math.cos(a)*age*157,200+Math.sin(a)*age*157,9,{shape:'flame'});}break;
   case 23:if(age<1.25)for(let j=0;j<3;j++)rect(id+j,130+j*170+row%2*35,200,age<.6?2:10,240,{warn:age<.6,angle:row%2?.2:-.2});break;
   case 24:if(age<1.25)rect(id,300,200,300,age<.6?3:200,{warn:age<.6,color:row%2?'orange':'cyan'});break;
   case 25:{const direction=row%4,a=direction*Math.PI/2,r=340-age*110-age*age*70;if(r>-30)add(id,300+Math.cos(a)*r,200+Math.sin(a)*r,11,{direction,shape:'crystal',warn:age<.2});break;}
   case 26:for(let j=0;j<4;j++){if(j===row%4)continue;rect(id+j,70+j*150,-25+age*145,23,23,{text:'□'});}break;
   case 27:if(age<1.5)add(id+'bomb',x,60+age*100,19,{warn:true,text:'!'});else if(age<2){rect(id+'h',300,210,300,10,{parent:'ut27:'+id+'bomb'});rect(id+'v',x,200,10,200,{parent:'ut27:'+id+'bomb'});}break;
   case 28:for(let j=0;j<5;j++){if(j===row%5)continue;add(id+j,630-age*215,65+j*65+Math.sin(age*3)*12,10,{text:'♪'});}break;
   case 29:if(age<1.1)add(id,x,age*175,20,{warn:age>.65});else for(let j=0;j<4;j++){const a=j*Math.PI/2+.4;add(id+j,x+Math.cos(a)*(age-1.1)*170,192+Math.sin(a)*(age-1.1)*170,8);}break;
   case 30:for(let j=0;j<4;j++)add(id+j,300+(j-1.5)*age*95,390-age*350+age*age*125,8,{shape:'flame'});break;
   case 31:add(id,-30+age*218,85+row%3*110,19,{text:'✦'});add(id+'green',-72+age*218,125+row%3*110,10,{color:'green'});break;
   case 32:{const px=630-age*210;rect(id,px,200,6,195,{color:'orange'});add(id+'knot',px,65+row%3*130,14,{shape:'flame'});break;}
   case 33:add(id,age<1.5?640-age*300:190+(age-1.5)*300,100+row%3*100,12,{text:'◒'});break;
   case 34:{w.marks??={};if(age<.5)w.marks[id]={x:w.x??300,y:w.y??200};const target=w.marks[id]||{x:300,y:200},a=Math.atan2(target.y, target.x-x),fly=Math.max(0,age-.5);add(id,x+Math.cos(a)*fly*285,Math.sin(a)*fly*285,10,{warn:age<.5,shape:'slash'});break;}
   case 35:for(let j=0;j<3;j++){add(id+'h'+j,-20+age*235,70+j*120+Math.sin(age*4)*22,7);add(id+'v'+j,80+j*210+Math.sin(age*4)*22,-20+age*185,7);}break;
  }
 }
 return out;
}

// Manual entries share tested arena primitives; narrative/UI effects become dodge patterns.
function soulManualHazards(w,t){
 const a=SOUL_MANUAL.find(a=>a.id===w.kind);if(!a)return [];
 w.manualSignature=a.signature;
 let out;
 if(a.mode==='shield')out=soulCatalogHazards({...w,kind:'a19'},t);
 else if(a.mechanic===0)out=soulBlasterHazards(w,t);
 else out=soulMechanicHazards(w,t,a.mechanic,0,'manual');
 if(a.mode==='web')out.forEach(p=>{if(!p.rect)p.y=100+Math.max(0,Math.min(2,Math.round((p.y-100)/100)))*100;});
 out.forEach((p,i)=>{
  if(a.color)p.color=a.color==='mixed'?(i%2?'orange':'cyan'):a.color;
  if(a.mode==='yellow'&&!p.warn)p.parent=p.id;
 });
 return out;
}
